#!/bin/bash

# TradeBot Sentinel - GitHub Secrets Setup Script
# This script helps configure GitHub repository secrets for CI/CD pipeline

set -e

# Colors for output
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
NC='\033[0m' # No Color

# Function to print colored output
print_status() {
    echo -e "${BLUE}[INFO]${NC} $1"
}

print_success() {
    echo -e "${GREEN}[SUCCESS]${NC} $1"
}

print_warning() {
    echo -e "${YELLOW}[WARNING]${NC} $1"
}

print_error() {
    echo -e "${RED}[ERROR]${NC} $1"
}

# Check if GitHub CLI is installed
check_gh_cli() {
    if ! command -v gh &> /dev/null; then
        print_error "GitHub CLI (gh) is not installed."
        print_status "Install it from: https://cli.github.com/"
        exit 1
    fi
    
    # Check if user is authenticated
    if ! gh auth status &> /dev/null; then
        print_error "Not authenticated with GitHub CLI."
        print_status "Run: gh auth login"
        exit 1
    fi
    
    print_success "GitHub CLI is installed and authenticated"
}

# Generate SSH key pair for deployment
generate_ssh_keys() {
    print_status "Generating SSH key pair for deployment..."
    
    SSH_KEY_PATH="$HOME/.ssh/tradebot_deploy"
    
    if [[ -f "$SSH_KEY_PATH" ]]; then
        print_warning "SSH key already exists at $SSH_KEY_PATH"
        read -p "Do you want to overwrite it? (y/N): " -n 1 -r
        echo
        if [[ ! $REPLY =~ ^[Yy]$ ]]; then
            print_status "Using existing SSH key"
            return
        fi
    fi
    
    ssh-keygen -t ed25519 -C "tradebot-deployment-$(date +%Y%m%d)" -f "$SSH_KEY_PATH" -N ""
    
    print_success "SSH key pair generated"
    print_status "Public key location: ${SSH_KEY_PATH}.pub"
    print_status "Private key location: $SSH_KEY_PATH"
    
    echo
    print_warning "IMPORTANT: Copy the public key to your VPS:"
    echo "ssh-copy-id -i ${SSH_KEY_PATH}.pub root@YOUR_VPS_IP"
    echo
}

# Collect configuration from user
collect_config() {
    print_status "Collecting configuration..."
    
    # Production server details
    read -p "Production VPS IP address: " PRODUCTION_HOST
    read -p "Production SSH user (default: tradebot): " PRODUCTION_USER
    PRODUCTION_USER=${PRODUCTION_USER:-tradebot}
    read -p "Production SSH port (default: 22): " PRODUCTION_SSH_PORT
    PRODUCTION_SSH_PORT=${PRODUCTION_SSH_PORT:-22}
    
    # Trading credentials
    read -p "Bulenox username: " BULENOX_USERNAME
    read -s -p "Bulenox password: " BULENOX_PASSWORD
    echo
    
    # Generate secure keys
    SECRET_KEY=$(openssl rand -hex 32)
    JWT_SECRET_KEY=$(openssl rand -hex 32)
    
    # Database configuration
    read -p "Database URL (default: postgresql://tradebot:password@localhost:5432/tradebot): " DATABASE_URL
    DATABASE_URL=${DATABASE_URL:-postgresql://tradebot:password@localhost:5432/tradebot}
    
    read -p "Redis URL (default: redis://localhost:6379/0): " REDIS_URL
    REDIS_URL=${REDIS_URL:-redis://localhost:6379/0}
    
    # Optional: Container registry
    read -p "Docker registry (optional, press enter to skip): " DOCKER_REGISTRY
    if [[ -n "$DOCKER_REGISTRY" ]]; then
        read -p "Docker username: " DOCKER_USERNAME
        read -s -p "Docker password/token: " DOCKER_PASSWORD
        echo
    fi
    
    # Optional: Slack notifications
    read -p "Slack webhook URL (optional, press enter to skip): " SLACK_WEBHOOK_URL
    
    # Optional: Email notifications
    read -p "SMTP host (optional, press enter to skip): " SMTP_HOST
    if [[ -n "$SMTP_HOST" ]]; then
        read -p "SMTP username: " SMTP_USERNAME
        read -s -p "SMTP password: " SMTP_PASSWORD
        echo
    fi
    
    print_success "Configuration collected"
}

# Set GitHub repository secrets
set_github_secrets() {
    print_status "Setting GitHub repository secrets..."
    
    # Read SSH private key
    SSH_PRIVATE_KEY=$(cat "$HOME/.ssh/tradebot_deploy" 2>/dev/null || echo "")
    
    if [[ -z "$SSH_PRIVATE_KEY" ]]; then
        print_error "SSH private key not found. Please generate SSH keys first."
        return 1
    fi
    
    # Set production server secrets
    gh secret set PRODUCTION_HOST --body "$PRODUCTION_HOST"
    gh secret set PRODUCTION_USER --body "$PRODUCTION_USER"
    gh secret set PRODUCTION_SSH_KEY --body "$SSH_PRIVATE_KEY"
    gh secret set PRODUCTION_SSH_PORT --body "$PRODUCTION_SSH_PORT"
    
    # Set application secrets
    gh secret set BULENOX_USERNAME --body "$BULENOX_USERNAME"
    gh secret set BULENOX_PASSWORD --body "$BULENOX_PASSWORD"
    gh secret set SECRET_KEY --body "$SECRET_KEY"
    gh secret set JWT_SECRET_KEY --body "$JWT_SECRET_KEY"
    gh secret set DATABASE_URL --body "$DATABASE_URL"
    gh secret set REDIS_URL --body "$REDIS_URL"
    
    # Set optional secrets
    if [[ -n "$DOCKER_REGISTRY" ]]; then
        gh secret set DOCKER_REGISTRY --body "$DOCKER_REGISTRY"
        gh secret set DOCKER_USERNAME --body "$DOCKER_USERNAME"
        gh secret set DOCKER_PASSWORD --body "$DOCKER_PASSWORD"
    fi
    
    if [[ -n "$SLACK_WEBHOOK_URL" ]]; then
        gh secret set SLACK_WEBHOOK_URL --body "$SLACK_WEBHOOK_URL"
    fi
    
    if [[ -n "$SMTP_HOST" ]]; then
        gh secret set SMTP_HOST --body "$SMTP_HOST"
        gh secret set SMTP_USERNAME --body "$SMTP_USERNAME"
        gh secret set SMTP_PASSWORD --body "$SMTP_PASSWORD"
    fi
    
    print_success "GitHub secrets configured successfully"
}

# Display summary
show_summary() {
    print_status "Configuration Summary:"
    echo "================================"
    echo "Production Host: $PRODUCTION_HOST"
    echo "Production User: $PRODUCTION_USER"
    echo "SSH Port: $PRODUCTION_SSH_PORT"
    echo "Database URL: $DATABASE_URL"
    echo "Redis URL: $REDIS_URL"
    
    if [[ -n "$DOCKER_REGISTRY" ]]; then
        echo "Docker Registry: $DOCKER_REGISTRY"
    fi
    
    if [[ -n "$SLACK_WEBHOOK_URL" ]]; then
        echo "Slack Notifications: Enabled"
    fi
    
    if [[ -n "$SMTP_HOST" ]]; then
        echo "Email Notifications: Enabled"
    fi
    
    echo "================================"
    echo
    print_success "GitHub Secrets Setup Complete!"
    echo
    print_status "Next Steps:"
    echo "1. Copy your SSH public key to the VPS:"
    echo "   ssh-copy-id -i ~/.ssh/tradebot_deploy.pub $PRODUCTION_USER@$PRODUCTION_HOST"
    echo "2. Test SSH connection:"
    echo "   ssh -i ~/.ssh/tradebot_deploy $PRODUCTION_USER@$PRODUCTION_HOST"
    echo "3. Push your code to trigger CI/CD:"
    echo "   git push origin main"
    echo "4. Monitor deployment in GitHub Actions tab"
}

# Main execution
main() {
    print_status "TradeBot Sentinel - GitHub Secrets Setup"
    echo "========================================"
    echo
    
    # Check prerequisites
    check_gh_cli
    
    # Generate SSH keys
    generate_ssh_keys
    
    # Collect configuration
    collect_config
    
    # Set GitHub secrets
    set_github_secrets
    
    # Show summary
    show_summary
}

# Run main function if script is executed directly
if [[ "${BASH_SOURCE[0]}" == "${0}" ]]; then
    main "$@"
